export type ConfigInput = {
    /**
     * Block outbound internet: the service only joins its environment's internal network. Omit to keep the current value on PATCH.
     */
    blockEgress?: boolean;
    buildContext?: string;
    /**
     * Where a git source is built: inherit (project, then team default), target, or build_server (pushed to a registry; the target pulls by digest)
     */
    buildLocation?: 'inherit' | 'target' | 'build_server';
    /**
     * Pin the build server; omitted lets the control plane choose a sticky one
     */
    buildServerId?: string;
    /**
     * How a git source is built: auto (Dockerfile if present, else Railpack), dockerfile, railpack or starter:<node|python|go|ruby|php|static>
     */
    buildType?: string;
    cpus?: number;
    /**
     * Typed container options. On every server: capAdd, capDrop, noNewPrivileges, readOnlyRootfs, pidsLimit, hostname (default: the service slug), dns, sysctls, hostSysctls (host requirements, only warned about), user, groupAdd, ulimits, shmSizeMb, extraHosts, labels, init, stopSignal, tmpfs, entrypoint. Only on a server an instance admin made unrestricted: devices, gpus, runtime, privileged, pidHost, seccompUnconfined, apparmorUnconfined and the capabilities NET_ADMIN and SYS_ADMIN (422 requires_unrestricted_server otherwise). Never host networking, ip, restart or log options, host binds or the socket.
     */
    docker?: DockerOptions;
    dockerfilePath?: string;
    files?: Array<FileMount> | null;
    gitBranch?: string;
    gitUrl?: string;
    healthcheck?: HealthcheckInput;
    image?: string;
    imageRetention?: number;
    memoryMb?: number;
    oneshot?: boolean;
    port?: number;
    postDeployCommand?: Array<string> | null;
    postDeployTimeoutSeconds?: number;
    preDeployCommand?: Array<string> | null;
    preDeployTimeoutSeconds?: number;
    /**
     * Name of the default process (the port, start command and health check above). Empty means web. Only meaningful with processes
     */
    processName?: string;
    /**
     * Additional named processes that share the service's image, variables, volumes and release. On PATCH the array replaces the whole list.
     */
    processes?: Array<ProcessInput> | null;
    /**
     * Registry the build is pushed to; omitted inherits the project or team default
     */
    registryId?: string;
    /**
     * The default process never runs two instances at once: the old instance stops before the new one starts, and scaling is off
     */
    singleton?: boolean;
    /**
     * The compose project of a stack: the compose file, per-component limits and the wait timeout. Components are derived by the server.
     */
    stack?: StackConfigInput;
    startCommand?: Array<string> | null;
    stopGraceSeconds?: number;
    /**
     * Git submodules: auto (recursive when the commit has a .gitmodules file; a submodule that cannot be fetched is only a warning; the default), on (always; a failure fails the build) or off. Credentials: the repository's token or deploy key is used for submodules on the same host only; relative URLs and ssh:// submodules of an HTTPS repository on the same host work, other hosts are fetched anonymously over https
     */
    submodules?: 'auto' | 'on' | 'off';
    tailnet?: TailnetConfig;
};

