export type CreateInputBodyWritable = {
    /**
     * Vault or OpenBao address, e.g. https://vault.example.com:8200
     */
    address?: string;
    /**
     * AppRole auth mount (default approle)
     */
    approleMount?: string;
    /**
     * token (default) or approle
     */
    authMethod?: 'token' | 'approle';
    /**
     * PEM certificate(s) to trust for a private CA (public material)
     */
    caCert?: string;
    /**
     * Machine identity client id (universal auth)
     */
    clientId?: string;
    /**
     * Doppler config used by references that name none (with defaultProject)
     */
    defaultConfig?: string;
    /**
     * Doppler project used by references that name none, like doppler:<name>#KEY. Set with defaultConfig, or leave both empty (a service token is bound to one config)
     */
    defaultProject?: string;
    /**
     * With scope selected: the projects (or single environments) allowed to reference the integration. At least one.
     */
    grants?: Array<ScopeGrantWritable> | null;
    /**
     * vault covers HashiCorp Vault and OpenBao (KV v2); doppler is Doppler (service token, or a personal / service account token with a project and config)
     */
    kind: 'vault' | 'infisical' | 'doppler';
    /**
     * KV v2 mount path (default secret)
     */
    mount?: string;
    /**
     * Lowercase letters, digits and dashes; it appears in references as vault:<name>/… or doppler:<name>/…
     */
    name: string;
    /**
     * Vault Enterprise / OpenBao namespace (X-Vault-Namespace)
     */
    namespace?: string;
    /**
     * Optional organization slug to scope the login to
     */
    organizationSlug?: string;
    /**
     * Infisical project id
     */
    projectId?: string;
    /**
     * AppRole role id
     */
    roleId?: string;
    /**
     * team (default on create): every project may reference the integration. selected: only the projects and environments in grants. Omit on update to keep the stored scope.
     */
    scope?: 'team' | 'selected';
    /**
     * Write-only: the Vault token (token auth), the AppRole secret id, the Infisical client secret or the Doppler token. Omit on update to keep the stored one.
     */
    secret?: string;
    /**
     * Infisical URL (default https://us.infisical.com) or Doppler API URL (default https://api.doppler.com)
     */
    siteUrl?: string;
};

